UPDATE t_user_coupon_expire_outbox
SET status='RETRY',retry_at=#{now},worker_id=NULL,lease_until=NULL,update_time=NOW()
WHERE status='PROCESSING' AND lease_until < #{now}

UPDATE t_user_coupon_expire_outbox
SET status='PUBLISHED',retry_at=#{nextCheckAt},worker_id=NULL,lease_until=NULL,update_time=NOW()
WHERE id=#{id} AND user_id=#{userId} AND status='PROCESSING' AND worker_id=#{workerId}

mapper.select:
SELECT id,user_coupon_id,user_id,coupon_template_id,valid_end_time,event_type,status,retry_at,attempts,
       worker_id,lease_until,last_error,create_time,update_time
FROM t_user_coupon_expire_outbox
WHERE status='PUBLISHED' AND retry_at <= #{now}
ORDER BY id ASC LIMIT #{limit}
